CREATE TABLE IF NOT EXISTS monster_templates (
    source_key varchar(32) NOT NULL,
    source_kind varchar(16) NOT NULL,
    source_map_id smallint,
    scene_key varchar(96) NOT NULL DEFAULT '',
    template_key varchar(128) NOT NULL,
    display_name varchar(255) NOT NULL DEFAULT '',
    rank varchar(16) NOT NULL DEFAULT 'normal',
    is_boss boolean NOT NULL DEFAULT false,
    is_elite boolean NOT NULL DEFAULT false,
    is_pet boolean NOT NULL DEFAULT false,
    attack_type smallint,
    model_file varchar(255) NOT NULL DEFAULT '',
    texture_file varchar(255) NOT NULL DEFAULT '',
    scale real,
    collision_range real,
    name_height real,
    stats jsonb NOT NULL DEFAULT '{}'::jsonb,
    PRIMARY KEY (source_key, template_key)
);

CREATE INDEX IF NOT EXISTS ix_monster_templates_source_map ON monster_templates (source_map_id);
CREATE INDEX IF NOT EXISTS ix_monster_templates_name ON monster_templates (display_name);
CREATE INDEX IF NOT EXISTS ix_monster_templates_rank ON monster_templates (rank);

ON CONFLICT (source_key, template_key) DO UPDATE
SET source_kind = EXCLUDED.source_kind,
    source_map_id = EXCLUDED.source_map_id,
    scene_key = EXCLUDED.scene_key,
    display_name = EXCLUDED.display_name,
    rank = EXCLUDED.rank,
    is_boss = EXCLUDED.is_boss,
    is_elite = EXCLUDED.is_elite,
    is_pet = EXCLUDED.is_pet,
    attack_type = EXCLUDED.attack_type,
    model_file = EXCLUDED.model_file,
    texture_file = EXCLUDED.texture_file,
    scale = EXCLUDED.scale,
    collision_range = EXCLUDED.collision_range,
    name_height = EXCLUDED.name_height,
    stats = EXCLUDED.stats;

CREATE TABLE IF NOT EXISTS quest_monster_references (
    quest_id integer PRIMARY KEY,
    monster_name varchar(255) NOT NULL DEFAULT '',
    map_id smallint,
    pos_x real,
    pos_z real,
    min_level integer,
    max_level integer,
    faction smallint,
    pet_group smallint,
    source varchar(64) NOT NULL DEFAULT ''
);

CREATE INDEX IF NOT EXISTS ix_quest_monster_references_map ON quest_monster_references (map_id);
CREATE INDEX IF NOT EXISTS ix_quest_monster_references_name ON quest_monster_references (monster_name);

ON CONFLICT (quest_id) DO UPDATE
SET monster_name = EXCLUDED.monster_name,
    map_id = EXCLUDED.map_id,
    pos_x = EXCLUDED.pos_x,
    pos_z = EXCLUDED.pos_z,
    min_level = EXCLUDED.min_level,
    max_level = EXCLUDED.max_level,
    faction = EXCLUDED.faction,
    pet_group = EXCLUDED.pet_group,
    source = EXCLUDED.source;

CREATE OR REPLACE VIEW monster_template_summary AS
SELECT
    COALESCE(mt.source_map_id, -1)::smallint AS map_id,
    mt.scene_key,
    COUNT(*) AS monster_count,
    COUNT(*) FILTER (WHERE mt.is_boss) AS boss_count,
    COUNT(*) FILTER (WHERE mt.is_elite) AS elite_count,
    COUNT(*) FILTER (WHERE mt.is_pet) AS pet_count
FROM monster_templates mt
GROUP BY COALESCE(mt.source_map_id, -1), mt.scene_key;

CREATE OR REPLACE VIEW boss_templates AS
SELECT *
FROM monster_templates
WHERE is_boss
ORDER BY source_map_id NULLS FIRST, display_name, template_key;
